mapper.select:


    inner join sys_user u on u.user_name = a.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    a.del_flag = '0'
    and a.task_wcs_id = #{taskWcsId}
    and a.erp_type = #{erpType}
    and a.send_data = #{sendData}
    and a.accept_data = #{acceptData}
    and a.status = #{status}


${params.dataScope}
order by a.create_time desc
